code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            color = grid[r][c]
            stack = [(r,c)]
            seen.add((r,c))
            comp = []
            while stack:
                rr,cc = stack.pop()
                comp.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != bg and (nr,nc) not in seen:
                        seen.add((nr,nc)); stack.append((nr,nc))
            components.append((color, comp))
    isolated = {}
    for color, comp in components:
        if len(comp) == 1:
            isolated[color] = isolated.get(color, 0) + 1
    marker = max(isolated, key=isolated.get)
    source = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg and grid[r][c] != marker]
    r0,r1 = min(r for r,c in source), max(r for r,c in source)
    c0,c1 = min(c for r,c in source), max(c for r,c in source)
    pattern = [[grid[r0+dr][c0+dc] for dc in range(c1-c0+1)] for dr in range(r1-r0+1)]
    out = [row[:] for row in grid]
    for r,c in [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]:
        top,left = r-len(pattern)//2, c-len(pattern[0])//2
        for dr in range(len(pattern)):
            for dc in range(len(pattern[0])):
                rr,cc = top+dr,left+dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = pattern[dr][dc]
    return out
'''
